using System;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
public class CPHInline {
 private static readonly object StateLock=String.Intern("streamercompanion:reactive-cameras:state:v1");
 private const string Key="portable.cameras.state", ReactiveKey="portable.reactive.state";
 private static bool? WasConnected;
 private string A(string key){return args.ContainsKey(key)&&args[key]!=null?args[key].ToString().Trim():"";}
 private string Read(string key){return CPH.GetGlobalVar<string>(key,true)??"";}
 private JObject State(){string raw=Read(Key);if(raw!="")return JObject.Parse(raw)["payload"] as JObject??throw new Exception("Camera state is invalid.");return new JObject{["config"]=new JObject{["version"]=1,["configured"]=false,["mainConfigured"]=false,["secondaryConfigured"]=false,["mainMode"]="off",["secondaryMode"]="off",["reactiveGuestId"]="",["videoSourceName"]="",["managedSecondarySources"]=new JArray(),["mappings"]=new JObject()},["status"]=new JObject{["status"]="unconfigured",["error"]=""}};}
 private void Save(JObject p){long revision=1;string old=Read(Key);if(old!="")revision=((long?)JObject.Parse(old)["revision"]??0)+1;p["moduleVersion"]="2.0.0";if(A("requestId")!="")p["lastRequestId"]=A("requestId");var e=new JObject{["schemaVersion"]=1,["feature"]="cameras",["type"]="state",["revision"]=revision,["payload"]=p};string json=e.ToString(Formatting.None);CPH.SetGlobalVar(Key,json,true);try{CPH.WebsocketBroadcastJson(json);}catch{}}
 private JObject Request(string type,JObject data=null){JObject response=JObject.Parse(CPH.ObsSendRaw(type,(data??new JObject()).ToString(Formatting.None)));if((bool?)response["requestStatus"]?["result"]==false)throw new Exception("OBS rejected "+type+".");return response["responseData"] as JObject??response;}
 private JObject Config(JObject p){return p["config"] as JObject??throw new Exception("Camera configuration is invalid.");}
 private string Map(JObject c,string key){return (string)c["mappings"]?[key]??"";}
 private JArray Guests(){string raw=Read(ReactiveKey);return raw==""?new JArray():JObject.Parse(raw)["payload"]?["guests"] as JArray??new JArray();}
 private JObject Guest(string id){return Guests().OfType<JObject>().FirstOrDefault(g=>(string)g["id"]==id);}
 private JArray Items(string scene){if(scene=="")throw new Exception("Choose the camera scene in Source mappings.");return Request("GetSceneItemList",new JObject{["sceneName"]=scene})["sceneItems"] as JArray??throw new Exception("OBS scene inventory is unavailable.");}
 private JObject Item(JArray items,string name){return items.OfType<JObject>().FirstOrDefault(i=>(string)i["sourceName"]==name);}
 private void Refresh(JObject p){bool connected=CPH.ObsIsConnected();p["obsAvailable"]=connected;p["obsError"]=connected?"":"OBS is disconnected.";p["reactiveGuests"]=Guests();p["videoInputs"]=new JArray();p["inputs"]=new JArray();p["scenes"]=new JArray();p["effective"]=new JObject{["mainItems"]=new JArray(),["secondaryItems"]=new JArray()};if(!connected)return;var c=Config(p);var inputs=Request("GetInputList")["inputs"] as JArray??new JArray();p["inputs"]=new JArray(inputs.Select(i=>new JObject{["name"]=(string)i["inputName"],["kind"]=(string)i["unversionedInputKind"]??(string)i["inputKind"]}));p["videoInputs"]=new JArray(((JArray)p["inputs"]).Where(i=>new[]{"window_capture","game_capture","dshow_input"}.Contains((string)i["kind"])&&!new[]{Map(c,"monitor"),Map(c,"laptop"),Map(c,"selfPng"),Map(c,"guestPng"),Map(c,"frame"),Map(c,"background")}.Contains((string)i["name"])));p["scenes"]=Request("GetSceneList")["scenes"] as JArray??new JArray();foreach(string slot in new[]{"main","secondary"}){string scene=Map(c,slot+"Scene");if(scene=="")continue;var rows=Items(scene);p["effective"][slot+"Items"]=new JArray(rows.Select(i=>new JObject{["sourceName"]=(string)i["sourceName"],["sceneItemId"]=i["sceneItemId"],["enabled"]=(bool?)i["sceneItemEnabled"]??false}));}}
 private string Mode(JObject c,string slot){return (string)c[slot=="main"?"mainMode":"secondaryMode"]??"off";}
 private string Chosen(JObject c,string slot){string mode=Mode(c,slot);if(mode=="off")return "";if(mode=="video")return (string)c["videoSourceName"]??"";return Map(c,mode=="png"?"selfPng":mode=="reactive"?"guestPng":mode);}
 private bool Managed(JObject c,string slot){return (bool?)c[slot=="main"?"mainConfigured":"secondaryConfigured"]??false;}
 private void Validate(JObject c,string slot){string mode=Mode(c,slot);if(!(slot=="main"?new[]{"off","monitor","laptop","png"}:new[]{"off","laptop","reactive","video"}).Contains(mode))throw new Exception("Unsupported camera mode.");string scene=Map(c,slot+"Scene");var items=Items(scene);string chosen=Chosen(c,slot);if(mode!="off"&&chosen=="")throw new Exception("Choose the source for this camera mode in Source mappings.");var inputs=Request("GetInputList")["inputs"] as JArray??new JArray();if(chosen!=""&&!inputs.Any(i=>(string)i["inputName"]==chosen))throw new Exception("Selected camera source is unavailable in OBS.");foreach(string decoration in new[]{"frame","background"}){string source=Map(c,decoration);if(source!=""&&Item(items,source)==null)throw new Exception("Mapped frame/background is missing from the camera scene.");}if(chosen!=""&&Item(items,chosen)==null&&mode!="video"&&mode!="laptop")throw new Exception("Selected source is missing from the camera scene.");if(mode=="reactive"){var guest=Guest((string)c["reactiveGuestId"]??"");Uri url;if(guest==null||!Uri.TryCreate((string)guest["url"],UriKind.Absolute,out url)||(url.Scheme!="http"&&url.Scheme!="https"))throw new Exception("Selected reactive guest is unavailable.");}}
 private void Visible(string scene,JObject item,bool value){if(item!=null)Request("SetSceneItemEnabled",new JObject{["sceneName"]=scene,["sceneItemId"]=item["sceneItemId"],["sceneItemEnabled"]=value});}
 private void ApplySlot(JObject c,string slot){string scene=Map(c,slot+"Scene"),mode=Mode(c,slot),chosen=Chosen(c,slot);var items=Items(scene);if(chosen!=""&&Item(items,chosen)==null){var created=Request("CreateSceneItem",new JObject{["sceneName"]=scene,["sourceName"]=chosen,["sceneItemEnabled"]=false});string template=Map(c,slot=="main"?"monitor":"laptop");var source=Item(items,template);if(source!=null){var transform=Request("GetSceneItemTransform",new JObject{["sceneName"]=scene,["sceneItemId"]=source["sceneItemId"]});Request("SetSceneItemTransform",new JObject{["sceneName"]=scene,["sceneItemId"]=created["sceneItemId"],["sceneItemTransform"]=transform["sceneItemTransform"]});}items=Items(scene);if(Item(items,chosen)==null)throw new Exception("OBS did not create the selected camera item.");}
  // Configure the selected input before hiding any currently visible content.
  if(chosen!=""&&(mode=="monitor"||mode=="laptop"))Request("SetInputSettings",new JObject{["inputName"]=chosen,["inputSettings"]=new JObject{["deactivate_when_not_showing"]=true},["overlay"]=true});
  if(mode=="png"||mode=="reactive"){var settings=new JObject{["shutdown"]=true,["restart_when_active"]=true};if(mode=="reactive")settings["url"]=(string)Guest((string)c["reactiveGuestId"])["url"];Request("SetInputSettings",new JObject{["inputName"]=chosen,["inputSettings"]=settings,["overlay"]=true});}
  var names=slot=="main"?new[]{Map(c,"monitor"),Map(c,"laptop"),Map(c,"selfPng")}.ToList():new[]{Map(c,"laptop"),Map(c,"guestPng")}.Concat((c["managedSecondarySources"] as JArray??new JArray()).Values<string>()).ToList();if(slot=="secondary"&&chosen!=""&&!names.Contains(chosen))names.Add(chosen);
  foreach(string name in names.Where(n=>n!="").Distinct())Visible(scene,Item(items,name),name==chosen);
  Visible(scene,Item(items,Map(c,"background")),mode=="png"||mode=="reactive");Visible(scene,Item(items,Map(c,"frame")),slot=="main"||mode!="off");
 }
 private void Apply(JObject p,string scope){if(!CPH.ObsIsConnected())throw new Exception("OBS is disconnected; saved camera settings were not applied.");var c=Config(p);var slots=new[]{"main","secondary"}.Where(s=>(scope=="both"||scope==s)&&Managed(c,s)).ToArray();foreach(string slot in slots)Validate(c,slot);var done=new JArray();p["status"]=new JObject{["status"]="applying",["error"]="",["appliedSlots"]=done};foreach(string slot in slots){ApplySlot(c,slot);done.Add(slot);}p["status"]["status"]="ok";p["status"]["appliedAtMs"]=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();}
 private void Mirror(JObject c){string raw=Read(ReactiveKey);if(raw=="")return;var e=JObject.Parse(raw);var p=e["payload"] as JObject;if(p==null)return;string id=Mode(c,"secondary")=="reactive"?(string)c["reactiveGuestId"]??"":"";if((string)p["camera2GuestId"]==id)return;p["camera2GuestId"]=id;e["revision"]=((long?)e["revision"]??0)+1;string json=e.ToString(Formatting.None);CPH.SetGlobalVar(ReactiveKey,json,true);try{CPH.WebsocketBroadcastJson(json);}catch{}}
 private bool Sync(JObject p){var c=Config(p);string id=(string)c["reactiveGuestId"]??"";if(id!=""&&Guest(id)==null){c["reactiveGuestId"]="";if(Mode(c,"secondary")=="reactive"){c["secondaryMode"]="off";if(Managed(c,"secondary"))Apply(p,"secondary");}Mirror(c);return true;}Mirror(c);return false;}
 public bool Execute(){lock(StateLock){JObject p=null;try{p=State();var c=Config(p);string mode=A("cameraActionMode");if(mode=="initialize"){if(c["mappings"]==null)c["mappings"]=new JObject();if((bool?)c["configured"]==true&&Map(c,"mainScene")!=""&&Map(c,"secondaryScene")!=""&&CPH.ObsIsConnected())Apply(p,"both");WasConnected=CPH.ObsIsConnected();Refresh(p);Save(p);return true;}
  if(mode=="observe"){bool connected=CPH.ObsIsConnected();bool changed=WasConnected.HasValue&&WasConnected.Value!=connected;WasConnected=connected;if(!connected){if(changed){p["obsAvailable"]=false;p["obsError"]="OBS is disconnected.";Save(p);}return true;}bool repaired=Sync(p);if(changed&&(bool?)c["configured"]==true)Apply(p,"both");if(changed||repaired){Refresh(p);Save(p);}return true;}
  if(mode=="refresh"||mode=="health"){Refresh(p);Save(p);return true;}
  if(mode=="mappings"){var mappings=JObject.Parse(A("mappings"));foreach(string key in new[]{"mainScene","secondaryScene","monitor","laptop","selfPng","guestPng","frame","background"})if(mappings[key]!=null&&mappings[key].Type!=JTokenType.String)throw new Exception("Source mappings must be text.");c["mappings"]=new JObject(mappings.Properties().Where(v=>new[]{"mainScene","secondaryScene","monitor","laptop","selfPng","guestPng","frame","background"}.Contains(v.Name)).Select(v=>new JProperty(v.Name,v.Value)));p["status"]=new JObject{["status"]="saved",["error"]=""};Refresh(p);Save(p);return true;}
  string scope=A("changedSlot");if(scope!="main"&&scope!="secondary")scope="both";
  if(mode=="configure"){foreach(string key in new[]{"mainMode","secondaryMode","reactiveGuestId","videoSourceName"})if(args.ContainsKey(key)&&(key=="mainMode"?scope!="secondary":scope!="main"))c[key]=A(key);if(scope=="main"||scope=="both")c["mainConfigured"]=true;if(scope=="secondary"||scope=="both")c["secondaryConfigured"]=true;c["configured"]=true;string video=(string)c["videoSourceName"]??"";var managed=c["managedSecondarySources"] as JArray??new JArray();if(scope!="main"&&video!=""&&!managed.Values<string>().Contains(video))managed.Add(video);c["managedSecondarySources"]=managed;}
  else if(mode=="assign-reactive"){if(Guest(A("id"))==null)throw new Exception("Selected reactive guest is unavailable.");c["secondaryMode"]="reactive";c["reactiveGuestId"]=A("id");c["secondaryConfigured"]=true;c["configured"]=true;scope="secondary";}
  else if(mode=="sync"){if(!Sync(p)&&Mode(c,"secondary")=="reactive")Apply(p,"secondary");Mirror(c);Refresh(p);Save(p);return true;}
  else if(mode!="reapply")throw new Exception("Unknown camera operation.");
  Apply(p,scope);Mirror(c);Refresh(p);Save(p);return true;
 }catch(Exception ex){if(p!=null){p["status"]=new JObject{["status"]="error",["error"]=ex.Message,["appliedSlots"]=p["status"]?["appliedSlots"]??new JArray()};try{Save(p);}catch{}}CPH.LogError("[cameras] Operation failed; inspect the private camera status.");return true;}}}
}
